const express = require('express');
const PDFDocument = require('pdfkit');
const axios = require('axios');

const app = express();

// Base64 encoded logo - replace this with your actual logo
// Using a simple 1x1 transparent PNG as placeholder
const logoBase64 = `data:image/jpeg;base64,`;

// Function to clean up mailto formatting in description text
function extractEmailFromDescription(text) {
  if (!text) return '';
  
  // Remove (mailto:email) parts but keep the email address
  // Pattern matches: [email](mailto:email) and replaces with just the email
  return text.replace(/\[([^\]]+)\]\(mailto:[^)]+\)/g, '$1');
}

app.get('/api/payment-request/:id', async (req, res) => {
  try {
    const { id } = req.params;
    
    // Fetch data from Kissflow
    const kissflowResponse = await axios.get(
      `https://alice-smith.kissflow.com/process/2/AcflcLIlo4aq/admin/Payment_Request/${id}`,
      {
        headers: {
          'X-Access-Key-Id': process.env.KISSFLOW_ACCESS_KEY_ID,
          'X-Access-Key-Secret': process.env.KISSFLOW_ACCESS_KEY_SECRET
        }
      }
    );
    
    const kissflowData = kissflowResponse.data;

    // Map Kissflow response fields to template variables
    const finalData = {
      payFormNumber: kissflowData.PAY_Form_Number || 'PAY-DEFAULT-001',
      requestedByFullName: kissflowData.Requester_Name_Hidden || kissflowData.Requested_By_Full_Name || 'Default User',
      requesterEmployeeId: kissflowData.Requested_By_Employee_Number || 'DEFAULT-001',
      requestedByEmail: kissflowData.Requested_By_Email || 'default@alice-smith.edu.my',
      requestedByDepartment: kissflowData.Requested_By_Department || 'Default Department',
      payTo: kissflowData.Pay_To || 'Default Payee',
      paymentMethod: kissflowData.Payment_Method || 'Default Method',
      budgetCode: kissflowData.Budget_Code_1_ID || 'DEFAULT-BUDGET',
      paymentDate: kissflowData.Payment_Date ? new Date(kissflowData.Payment_Date).toLocaleDateString('en-CA') : new Date().toLocaleDateString('en-CA'),
      paymentDetails: kissflowData['Table::Payment_Request_Details_Budget_Code_1'] && Array.isArray(kissflowData['Table::Payment_Request_Details_Budget_Code_1']) && kissflowData['Table::Payment_Request_Details_Budget_Code_1'].length > 0 ? kissflowData['Table::Payment_Request_Details_Budget_Code_1'].map(item => ({
        date: item.Transaction_Date_Input ? new Date(item.Transaction_Date_Input).toLocaleDateString('en-CA') : new Date().toLocaleDateString('en-CA'),
        reference: item.Document_Reference_1 || '',
        description: extractEmailFromDescription(item.Decsription || ''),
        amount: item.Amount_MYR || '0.00'
      })) : [],
      totalSpent: kissflowData.Table_1_Spent_MYR || '0.00 MYR'
    };

    // Generate filename based on Payment Request number
    const filename = `${finalData.payFormNumber}.pdf`;

    // Create PDF document
    const doc = new PDFDocument({ size: 'A4' });
    
    // Set response headers
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    
    // Pipe the PDF to response
    doc.pipe(res);

    // Calculate page dimensions
    const pageWidth = doc.page.width - 100; // Full width minus margins

    // Add logo
    if (logoBase64) {
      try {
        const logoHeight = 80; // Increased height for better visibility
        const logoX = 50; // Start from left margin
        
        doc.image(logoBase64, logoX, 50, {
          width: pageWidth,
          height: logoHeight
        });
      } catch (logoError) {
        console.warn('Logo rendering failed, continuing without logo:', logoError.message);
        // Continue without logo if it fails
      }
    }

    // Add title
    doc.fontSize(20)
       .font('Helvetica-Bold')
       .text('Payment Request', 50, 150, { align: 'center' });

    // Add form number
    doc.fontSize(12)
       .font('Helvetica')
       .text(finalData.payFormNumber, 50, 180, { align: 'center' });

    // Add requester and payment details table with dynamic heights
    const tableTop = 220;
    const colWidths = [130, 170, 110, 190]; // Field1, Value1, Field2, Value2 - increased second value column for department
    let requesterCurrentRowY = tableTop;
    
    // Table data rows - 4 rows with 2 field-value pairs each
    const tableData = [
      [
        { label: 'Requested By Full Name', value: finalData.requestedByFullName },
        { label: 'Requester Employee ID', value: finalData.requesterEmployeeId }
      ],
      [
        { label: 'Requested By Email', value: finalData.requestedByEmail },
        { label: 'Requested By Department', value: finalData.requestedByDepartment }
      ],
      [
        { label: 'Pay To', value: finalData.payTo },
        { label: 'Payment Method', value: finalData.paymentMethod }
      ],
      [
        { label: 'Budget Code', value: finalData.budgetCode },
        { label: 'Payment Date', value: finalData.paymentDate }
      ]
    ];
    
    // Draw table rows with dynamic heights
    tableData.forEach((row, index) => {
      // Calculate dynamic row height based on content
      const label1Height = doc.heightOfString(row[0].label, {
        width: colWidths[0] - 10,
        align: 'left'
      });
      
      const value1Height = doc.heightOfString(row[0].value, {
        width: colWidths[1] - 10,
        align: 'left'
      });
      
      const label2Height = doc.heightOfString(row[1].label, {
        width: colWidths[2] - 10,
        align: 'left'
      });
      
      const value2Height = doc.heightOfString(row[1].value, {
        width: colWidths[3] - 10,
        align: 'left'
      });
      
      // Use the maximum height needed for this row
      const rowHeight = Math.max(20, Math.max(label1Height, value1Height, label2Height, value2Height) + 10);
      
      // Draw row background
      doc.rect(50, requesterCurrentRowY, 500, rowHeight).stroke();
      
      // Add row data - first field-value pair (ensure black color)
      doc.fontSize(10).font('Helvetica').fillColor('black').text(row[0].label, 55, requesterCurrentRowY + 5, { width: colWidths[0] - 10 });
      doc.font('Helvetica').fillColor('black').text(row[0].value, 185, requesterCurrentRowY + 5, { width: colWidths[1] - 10 });
      
      // Add row data - second field-value pair (ensure black color)
      doc.font('Helvetica').fillColor('black').text(row[1].label, 335, requesterCurrentRowY + 5, { width: colWidths[2] - 10 });
      doc.font('Helvetica').fillColor('black').text(row[1].value, 445, requesterCurrentRowY + 5, { width: colWidths[3] - 10 });
      
      // Draw vertical lines
      doc.moveTo(180, requesterCurrentRowY)
         .lineTo(180, requesterCurrentRowY + rowHeight)
         .stroke();
      doc.moveTo(330, requesterCurrentRowY)
         .lineTo(330, requesterCurrentRowY + rowHeight)
         .stroke();
      doc.moveTo(440, requesterCurrentRowY)
         .lineTo(440, requesterCurrentRowY + rowHeight)
         .stroke();
      
      // Move to next row
      requesterCurrentRowY += rowHeight;
    });
    
    // Calculate total table height
    const tableHeight = requesterCurrentRowY - tableTop;

    // Draw second table - itemized budget details (only if there are payment details)
    if (finalData.paymentDetails.length > 0) {
      const table2Top = tableTop + tableHeight + 40; // Increased gap from 20 to 40
      
      // Draw table header with borders (same width as requester table)
      doc.rect(50, table2Top, 500, 20).stroke();
      doc.rect(50, table2Top, 500, 20).fill('#e8e8e8');

      // Add header texts
      const headers2 = ['Date', 'Reference', 'Description', 'Amount'];
      const col2Widths = [100, 120, 200, 80]; // Adjusted to total 500px
      currentX = 50;
      
      headers2.forEach((header, i) => {
        doc.font('Helvetica-Bold')
           .fillColor('black')
           .text(header, currentX + 5, table2Top + 5, { width: col2Widths[i] });
        
        // Draw vertical lines
        if (i < headers2.length) {
          doc.moveTo(currentX, table2Top)
             .lineTo(currentX, table2Top + 20 + (finalData.paymentDetails.length * 20))
             .stroke();
        }
        currentX += col2Widths[i];
      });
      // Last vertical line
      doc.moveTo(currentX, table2Top)
         .lineTo(currentX, table2Top + 20 + (finalData.paymentDetails.length * 20))
         .stroke();

      // Draw horizontal line after header
      doc.moveTo(50, table2Top + 20)
         .lineTo(500, table2Top + 20)
         .stroke();

    // Add table data with dynamic row heights and page break handling
    let currentRowY = table2Top + 25;
    let isFirstPage = true;
    
    finalData.paymentDetails.forEach((item, index) => {
      // Calculate dynamic row height based on content
      const dateHeight = doc.heightOfString(item.date, {
        width: col2Widths[0] - 10,
        align: 'left'
      });
      
      const referenceHeight = doc.heightOfString(item.reference, {
        width: col2Widths[1] - 10,
        align: 'left'
      });
      
      const descriptionHeight = doc.heightOfString(item.description, {
        width: col2Widths[2] - 10,
        align: 'left'
      });
      
      const amountHeight = doc.heightOfString(item.amount + ' MYR', {
        width: col2Widths[3] - 10,
        align: 'left'
      });
      
      // Use the maximum height needed for this row
      const rowHeight = Math.max(20, Math.max(dateHeight, referenceHeight, descriptionHeight, amountHeight) + 10);
      
      // Check if we need a new page (leave space for total section)
      if (currentRowY + rowHeight > doc.page.height - 100) {
        doc.addPage();
        currentRowY = 50; // Start from top of new page
        
        // Redraw table header on new page
        doc.rect(50, currentRowY, 500, 20).stroke();
        doc.rect(50, currentRowY, 500, 20).fill('#e8e8e8');
        
        // Add header texts on new page
        let headerX = 50;
        headers2.forEach((header, i) => {
          doc.font('Helvetica-Bold')
             .fillColor('black')
             .text(header, headerX + 5, currentRowY + 5, { width: col2Widths[i] });
          headerX += col2Widths[i];
        });
        
        // Draw vertical lines for header on new page
        headerX = 50;
        for (let i = 0; i <= col2Widths.length; i++) {
          doc.moveTo(headerX, currentRowY)
             .lineTo(headerX, currentRowY + 20)
             .stroke();
          headerX += col2Widths[i] || 0;
        }
        
        // Draw horizontal line after header on new page
        doc.moveTo(50, currentRowY + 20)
           .lineTo(500, currentRowY + 20)
           .stroke();
        
        currentRowY += 25; // Move past header
        isFirstPage = false;
      }
      
      // Draw row background and borders (same width as requester table)
      doc.rect(50, currentRowY - 5, 500, rowHeight).stroke();
      
      doc.font('Helvetica').fontSize(10).fillColor('black');
      
      let x = 50;
      doc.text(item.date, x + 5, currentRowY, { width: col2Widths[0] - 10 });
      x += col2Widths[0];
      
      doc.text(item.reference, x + 5, currentRowY, { width: col2Widths[1] - 10 });
      x += col2Widths[1];
      
      doc.text(item.description, x + 5, currentRowY, { width: col2Widths[2] - 10 });
      x += col2Widths[2];
      
      doc.text(item.amount + ' MYR', x + 5, currentRowY, { width: col2Widths[3] - 10 });
      
      // Draw vertical lines for this row
      x = 50;
      for (let i = 0; i <= col2Widths.length; i++) {
        doc.moveTo(x, currentRowY - 5)
           .lineTo(x, currentRowY + rowHeight)
           .stroke();
        x += col2Widths[i] || 0;
      }
      
      // Move to next row
      currentRowY += rowHeight;
    });

      // Draw bottom border of second table (using currentRowY position)
      doc.moveTo(50, currentRowY)
         .lineTo(550, currentRowY)
         .stroke();

      // Add total at bottom right - check if we need a new page for total
      let totalY = currentRowY + 20;
      if (totalY > doc.page.height - 50) {
        doc.addPage();
        totalY = 50;
      }
      
      doc.fontSize(12)
         .font('Helvetica-Bold')
         .fillColor('black')
         .text('Total:', 350, totalY)
         .text(finalData.totalSpent, 400, totalY);
    } else {
      // If no payment details, just show the total
      const totalY = tableTop + tableHeight + 60; // Position below the requester table
      doc.fontSize(12)
         .font('Helvetica-Bold')
         .fillColor('black')
         .text('Total:', 350, totalY)
         .text(finalData.totalSpent, 400, totalY);
    }

    // Finalize the PDF and end the stream
    doc.end();

  } catch (error) {
    console.error('Error generating Payment Request PDF:', error);
    res.status(500).json({ 
      error: 'Error generating Payment Request PDF', 
      details: error.message 
    });
  }
});

module.exports = app;
